	/**
	 * Method to retrieve the MessagingEndpoint via MessagingEndpointFetchOneSummary
	 * @param 	summary MessagingEndpointFetchOneSummary
	 * @return 	MessagingEndpointFetchOneResponse
	 */
	public MessagingEndpoint getMessagingEndpoint( MessagingEndpointFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "MessagingEndpointFetchOneSummary arg cannot be null" );

		MessagingEndpoint entity = null;
		UUID id = summary.getMessagingEndpointId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a MessagingEndpoint using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all MessagingEndpoints
	 *
	 * @return 	List<MessagingEndpoint>
	 */
    public List<MessagingEndpoint> getAllMessagingEndpoint() {
		List<MessagingEndpoint> list = projector.findAll( new FindAllMessagingEndpointQuery() );
		return list;
	}

	/**
	 * assign Tenant on MessagingEndpoint
	 * @param		command AssignTenantToMessagingEndpointCommand
	 */
	public void assignTenant( AssignTenantToMessagingEndpointCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignTenant(command.getMessagingEndpointId(), command.getAssignment());

	}

